ALTER TABLE  AUTORIZZAZIONI_SUBENTRI DROP COLUMN STAGIONALE_DA;
ALTER TABLE  AUTORIZZAZIONI_SUBENTRI DROP COLUMN STAGIONALE_A;

ALTER TABLE  AUTORIZZAZIONI_SUBENTRI add STAGIONALE_DA VARCHAR(4);
ALTER TABLE  AUTORIZZAZIONI_SUBENTRI add STAGIONALE_A VARCHAR(4);


UPDATE AUTORIZZAZIONI_SUBENTRI A 
	JOIN AUTORIZZAZIONI_CONCESSIONI B 
	ON A.IDCOMUNE = B.IDCOMUNE AND A.FK_IDAUT_ATTUALE = B.FK_IDAUT_ATTUALE   
 SET A.STAGIONALE_DA = B.STAGIONALEDA 
 WHERE A.STAGIONALE_DA IS NULL;
 
UPDATE AUTORIZZAZIONI_SUBENTRI A 
    JOIN AUTORIZZAZIONI_CONCESSIONI B ON A.IDCOMUNE = B.IDCOMUNE 
    AND  A.FK_IDAUT_ATTUALE = B.FK_IDAUT_ATTUALE
    SET A.STAGIONALE_A = B.STAGIONALEA
 WHERE A.STAGIONALE_A IS NULL;
             


