CREATE OR REPLACE ALGORITHM=MERGE VIEW VW_COMUNIASSOCIATIINFO AS SELECT COMUNIASSOCIATI.*, COMUNI.CODICEISTAT FROM COMUNIASSOCIATI INNER JOIN COMUNI ON COMUNIASSOCIATI.CODICECOMUNE = COMUNI.CODICECOMUNE;

CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_ISTANZECONCESSIONILISTA AS SELECT 99999999 AS PROGRESSIVO, AUTORIZZAZIONI.AUTORIZRESPONSABILE AS CONC_AUTORIZRESPONSABILE, AUTORIZZAZIONI.IDCOMUNE, AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AS ICONC_CODICECAUSALE, IFNULL(AUTORIZZAZIONI.DATA_CESSAZIONE,STR_TO_DATE('31/12/9999','%d/%m/%Y')) AS DATA_STORICO, ISTANZE.SOFTWARE, ISTANZE.CODICEISTANZA AS IST_CODICEISTANZA, ISTANZE.NUMEROISTANZA AS IST_NUMEROISTANZA, ISTANZE.CODICERICHIEDENTE AS IST_CODICERICHIEDENTE, AUTORIZZAZIONI.ID AS CONC_ID, AUTORIZZAZIONI.AUTORIZNUMERO AS CONC_NUMERO, AUTORIZZAZIONI.AUTORIZDATA AS CONC_DATARILASCIO, AUTORIZZAZIONI.AUTORIZDATA AS DATARILASCIO, AUTORIZZAZIONI.DATASCADENZA AS CONC_DATASCADENZA, AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AS CONC_CODICETIPO, CONCESSIONITIPI.DESCRIZIONE AS CONC_TIPO, AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA AS CONC_STAGIONALEA, AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA AS CONC_STAGIONALEDA, AUTORIZZAZIONI.FLAG_ATTIVA AS CONC_ATTIVA, AUTORIZZAZIONI.FK_CODICEANAGRAFE AS CONC_CODICETITOLARE, AUTORIZZAZIONI.FKIDREGISTRO AS CONC_FKIDREGISTRO, CONC_REGISTRO.TR_DESCRIZIONE AS CONC_REGISTRO, CONCAT_WS('',TITOLARE.NOMINATIVO,' ',TITOLARE.NOME) AS CONC_TITOLARE, TITOLARE.CODICEFISCALE AS CONC_TIT_CF, TITOLARE.PARTITAIVA AS CONC_TIT_PIVA, TITOLARE.TIPOANAGRAFE AS CONC_TIT_TIPOANAGRAFE, AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO, AUT_COLLEGATA.AUTORIZDATA AS AUT_DATA, AUT_COLLEGATA.AUTORIZDATA, AUT_COLLEGATA.FKIDREGISTRO AS AUT_CODREGISTRO, TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO, CONCAT_WS('',IST_RICHIEDENTE.NOMINATIVO,' ',IST_RICHIEDENTE.NOME) AS IST_NOMINATIVO, IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE, CONCAT_WS('',IST_AZIENDA.NOMINATIVO,' ',IST_AZIENDA.NOME) AS IST_NOMINATIVOAZIENDA, IST_AZIENDA.TIPOANAGRAFE AS IST_AZI_TIPOANAGRAFE, IST_RICHIEDENTE.CODICEFISCALE AS IST_CODICEFISCALE, IST_RICHIEDENTE.PARTITAIVA AS IST_PARTITAIVA, CAUS_ATTUALE.DESCRIZIONE AS ICONC_CAUSALE, AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE AS ICONC_CODICECAUSALESTORICO, CAUS_STORICO.DESCRIZIONE AS ICONC_CAUSALESTORICO, AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AS CONC_IDMERCATO, MERCATI.DESCRIZIONE AS CONC_MERCATO, MERCATI.ATTIVO AS MERC_ATTIVO, AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AS CONC_IDPOSTEGGIO, MERCATI_D.CODICEPOSTEGGIO AS CONC_POSTEGGIO, MERCATI_D.LARGHEZZA AS CONC_POS_LARGHEZZA, MERCATI_D.LUNGHEZZA AS CONC_POS_LUNGHEZZA, MERCATI_D.SUPERFICIE AS CONC_POS_SUPERFICIE, MERCATI_D.FKCODICETIPOSPAZIO AS POST_IDTIPOSPAZIO, POSTEGGITIPOSPAZIO.TIPOSPAZIO AS POST_TIPOSPAZIO, AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AS CONC_IDMERCATIUSO, MERCATI_USO.DESCRIZIONE AS CONC_DESCRIZIONEUSO, MERCATI_USO.PESO AS PESO_MERCATO, MERCATI_USO.FKCODICEUSO AS MERC_IDUSO, MERCATI_D.FKCODICESTRADARIO AS CONC_POS_CODICESTRADARIO, MERCATI_D.NOTE AS CONC_POS_NOTE, VW_ENTILOCALI.COMUNE AS CONC_ENTERILASCIO FROM AUTORIZZAZIONI INNER JOIN TIPOLOGIAREGISTRI CONC_REGISTRO ON AUTORIZZAZIONI.IDCOMUNE = CONC_REGISTRO.IDCOMUNE AND AUTORIZZAZIONI.FKIDREGISTRO = CONC_REGISTRO.TR_ID INNER JOIN AUTORIZZAZIONI_CONCESSIONI ON AUTORIZZAZIONI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE LEFT  JOIN AUTORIZZAZIONI AUT_COLLEGATA ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE = AUT_COLLEGATA.IDCOMUNE AND AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA = AUT_COLLEGATA.ID LEFT  JOIN TIPOLOGIAREGISTRI ON AUT_COLLEGATA.IDCOMUNE = TIPOLOGIAREGISTRI.IDCOMUNE AND AUT_COLLEGATA.FKIDREGISTRO = TIPOLOGIAREGISTRI.TR_ID INNER JOIN CONCESSIONITIPI ON AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE = CONCESSIONITIPI.TIPOCONCESSIONE INNER JOIN ANAGRAFE TITOLARE ON AUTORIZZAZIONI.IDCOMUNE = TITOLARE.IDCOMUNE AND AUTORIZZAZIONI.FK_CODICEANAGRAFE = TITOLARE.CODICEANAGRAFE INNER JOIN CONCESSIONICAUSALI CAUS_ATTUALE ON AUTORIZZAZIONI.IDCOMUNE = CAUS_ATTUALE.IDCOMUNE AND AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE = CAUS_ATTUALE.CODICECAUSALE LEFT  JOIN CONCESSIONICAUSALI CAUS_STORICO ON AUTORIZZAZIONI.IDCOMUNE = CAUS_STORICO.IDCOMUNE AND AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE = CAUS_STORICO.CODICECAUSALE INNER JOIN ISTANZE ON AUTORIZZAZIONI.IDCOMUNE = ISTANZE.IDCOMUNE AND AUTORIZZAZIONI.FKIDISTANZA = ISTANZE.CODICEISTANZA INNER JOIN ANAGRAFE IST_RICHIEDENTE ON ISTANZE.IDCOMUNE = IST_RICHIEDENTE.IDCOMUNE AND ISTANZE.CODICERICHIEDENTE = IST_RICHIEDENTE.CODICEANAGRAFE INNER JOIN MERCATI ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE = MERCATI.IDCOMUNE AND AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO = MERCATI.CODICEMERCATO INNER JOIN MERCATI_D ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE = MERCATI_D.IDCOMUNE AND AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO = MERCATI_D.IDPOSTEGGIO LEFT  JOIN POSTEGGITIPOSPAZIO ON MERCATI_D.IDCOMUNE = POSTEGGITIPOSPAZIO.IDCOMUNE AND MERCATI_D.FKCODICETIPOSPAZIO = POSTEGGITIPOSPAZIO.CODICE INNER JOIN MERCATI_USO ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE = MERCATI_USO.IDCOMUNE AND AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO = MERCATI_USO.ID LEFT  JOIN ANAGRAFE IST_AZIENDA ON ISTANZE.IDCOMUNE = IST_AZIENDA.IDCOMUNE AND ISTANZE.CODICETITOLARELEGALE = IST_AZIENDA.CODICEANAGRAFE INNER JOIN VW_ENTILOCALI ON AUTORIZZAZIONI.AUTORIZCOMUNE = VW_ENTILOCALI.CODICECOMUNE UNION SELECT AUTORIZZAZIONI_SUBENTRI.ID AS PROGRESSIVO, AUTORIZZAZIONI_SUBENTRI.AUTORIZRESPONSABILE AS CONC_AUTORIZRESPONSABILE, AUTORIZZAZIONI_SUBENTRI.IDCOMUNE, AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE AS ICONC_CODICECAUSALE, AUTORIZZAZIONI_SUBENTRI.DATA_CESSAZIONE AS DATA_STORICO, ISTANZE.SOFTWARE, ISTANZE.CODICEISTANZA AS IST_CODICEISTANZA, ISTANZE.NUMEROISTANZA AS IST_NUMEROISTANZA, ISTANZE.CODICERICHIEDENTE AS IST_CODICERICHIEDENTE, AUTORIZZAZIONI_SUBENTRI.FK_IDAUT_ATTUALE AS CONC_ID, AUTORIZZAZIONI_SUBENTRI.AUTORIZNUMERO AS CONC_NUMERO, AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA AS CONC_DATARILASCIO, AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA AS DATARILASCIO, AUTORIZZAZIONI_SUBENTRI.DATASCADENZA AS CONC_DATASCADENZA, AUTORIZZAZIONI_SUBENTRI_CONC.FK_TIPOCONCESSIONE AS CONC_CODICETIPO, CONCESSIONITIPI.DESCRIZIONE AS CONC_TIPO, AUTORIZZAZIONI_SUBENTRI_CONC.STAGIONALEA AS CONC_STAGIONALEA, AUTORIZZAZIONI_SUBENTRI_CONC.STAGIONALEDA AS CONC_STAGIONALEDA, 0 AS CONC_ATTIVA, AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE AS CONC_CODICETITOLARE, AUTORIZZAZIONI_SUBENTRI.FKIDREGISTRO AS CONC_FKIDREGISTRO, CONC_REGISTRO.TR_DESCRIZIONE AS CONC_REGISTRO, CONCAT_WS('',TITOLARE.NOMINATIVO,' ',TITOLARE.NOME) AS CONC_TITOLARE, TITOLARE.CODICEFISCALE AS CONC_TIT_CF, TITOLARE.PARTITAIVA AS CONC_TIT_PIVA, TITOLARE.TIPOANAGRAFE AS CONC_TIT_TIPOANAGRAFE, AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO, AUT_COLLEGATA.AUTORIZDATA AS AUT_DATA, AUT_COLLEGATA.AUTORIZDATA, AUT_COLLEGATA.FKIDREGISTRO AS AUT_CODREGISTRO, TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO, CONCAT_WS('',IST_RICHIEDENTE.NOMINATIVO,' ',IST_RICHIEDENTE.NOME) AS IST_NOMINATIVO, IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE, CONCAT_WS('',IST_AZIENDA.NOMINATIVO,' ',IST_AZIENDA.NOME) AS IST_NOMINATIVOAZIENDA, IST_AZIENDA.TIPOANAGRAFE AS IST_AZI_TIPOANAGRAFE, IST_RICHIEDENTE.CODICEFISCALE AS IST_CODICEFISCALE, IST_RICHIEDENTE.PARTITAIVA AS IST_PARTITAIVA, CAUS_ATTUALE.DESCRIZIONE AS ICONC_CAUSALE, AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_CESSAZIONE AS ICONC_CODICECAUSALESTORICO, CAUS_STORICO.DESCRIZIONE AS ICONC_CAUSALESTORICO, AUTORIZZAZIONI_SUBENTRI_CONC.FK_CODICEMERCATO AS CONC_IDMERCATO, MERCATI.DESCRIZIONE AS CONC_MERCATO, MERCATI.ATTIVO AS MERC_ATTIVO, AUTORIZZAZIONI_SUBENTRI_CONC.FK_IDPOSTEGGIO AS CONC_IDPOSTEGGIO, MERCATI_D.CODICEPOSTEGGIO AS CONC_POSTEGGIO, MERCATI_D.LARGHEZZA AS CONC_POS_LARGHEZZA, MERCATI_D.LUNGHEZZA AS CONC_POS_LUNGHEZZA, MERCATI_D.SUPERFICIE AS CONC_POS_SUPERFICIE, MERCATI_D.FKCODICETIPOSPAZIO AS POST_IDTIPOSPAZIO, POSTEGGITIPOSPAZIO.TIPOSPAZIO AS POST_TIPOSPAZIO, AUTORIZZAZIONI_SUBENTRI_CONC.FK_IDMERCATIUSO AS CONC_IDMERCATIUSO, MERCATI_USO.DESCRIZIONE AS CONC_DESCRIZIONEUSO, MERCATI_USO.PESO AS PESO_MERCATO, MERCATI_USO.FKCODICEUSO AS MERC_IDUSO, MERCATI_D.FKCODICESTRADARIO AS CONC_POS_CODICESTRADARIO, MERCATI_D.NOTE AS CONC_POS_NOTE, VW_ENTILOCALI.COMUNE AS CONC_ENTERILASCIO FROM AUTORIZZAZIONI_SUBENTRI INNER JOIN TIPOLOGIAREGISTRI CONC_REGISTRO ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE = CONC_REGISTRO.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.FKIDREGISTRO = CONC_REGISTRO.TR_ID INNER JOIN AUTORIZZAZIONI_SUBENTRI_CONC ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI_CONC.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.ID = AUTORIZZAZIONI_SUBENTRI_CONC.FK_AUTSUB_ID LEFT  JOIN AUTORIZZAZIONI_SUBENTRI AUT_COLLEGATA ON AUTORIZZAZIONI_SUBENTRI_CONC.IDCOMUNE = AUT_COLLEGATA.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI_CONC.FK_IDAUTSUB_AUTCOLL = AUT_COLLEGATA.ID LEFT  JOIN TIPOLOGIAREGISTRI ON AUT_COLLEGATA.IDCOMUNE = TIPOLOGIAREGISTRI.IDCOMUNE AND AUT_COLLEGATA.FKIDREGISTRO = TIPOLOGIAREGISTRI.TR_ID INNER JOIN CONCESSIONITIPI ON AUTORIZZAZIONI_SUBENTRI_CONC.FK_TIPOCONCESSIONE = CONCESSIONITIPI.TIPOCONCESSIONE INNER JOIN ANAGRAFE TITOLARE ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE = TITOLARE.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE = TITOLARE.CODICEANAGRAFE INNER JOIN CONCESSIONICAUSALI CAUS_ATTUALE ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE = CAUS_ATTUALE.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE = CAUS_ATTUALE.CODICECAUSALE LEFT  JOIN CONCESSIONICAUSALI CAUS_STORICO ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE = CAUS_STORICO.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_CESSAZIONE = CAUS_STORICO.CODICECAUSALE INNER JOIN ISTANZE ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE = ISTANZE.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.FKIDISTANZA = ISTANZE.CODICEISTANZA INNER JOIN ANAGRAFE IST_RICHIEDENTE ON ISTANZE.IDCOMUNE = IST_RICHIEDENTE.IDCOMUNE AND ISTANZE.CODICERICHIEDENTE = IST_RICHIEDENTE.CODICEANAGRAFE INNER JOIN MERCATI ON AUTORIZZAZIONI_SUBENTRI_CONC.IDCOMUNE = MERCATI.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI_CONC.FK_CODICEMERCATO = MERCATI.CODICEMERCATO INNER JOIN MERCATI_D ON AUTORIZZAZIONI_SUBENTRI_CONC.IDCOMUNE = MERCATI_D.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI_CONC.FK_IDPOSTEGGIO = MERCATI_D.IDPOSTEGGIO LEFT  JOIN POSTEGGITIPOSPAZIO ON MERCATI_D.IDCOMUNE = POSTEGGITIPOSPAZIO.IDCOMUNE AND MERCATI_D.FKCODICETIPOSPAZIO = POSTEGGITIPOSPAZIO.CODICE INNER JOIN MERCATI_USO ON AUTORIZZAZIONI_SUBENTRI_CONC.IDCOMUNE = MERCATI_USO.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI_CONC.FK_IDMERCATIUSO = MERCATI_USO.ID LEFT  JOIN ANAGRAFE IST_AZIENDA ON ISTANZE.IDCOMUNE = IST_AZIENDA.IDCOMUNE AND ISTANZE.CODICETITOLARELEGALE = IST_AZIENDA.CODICEANAGRAFE INNER JOIN VW_ENTILOCALI ON AUTORIZZAZIONI_SUBENTRI.AUTORIZCOMUNE = VW_ENTILOCALI.CODICECOMUNE;
